func:
// Recupere les dernieres valeurs stockees
let ac = context.get('ac') || null;
let dc = context.get('dc') || null;

// Mise a jour selon le topic
if (msg.topic.includes('Ac/Power')) {
    ac = msg.payload;
    context.set('ac', ac);
    node.log('AC updated: ' + ac);
} else if (msg.topic.includes('Dc/Pv/Power')) {
    dc = msg.payload;
    context.set('dc', dc);
    node.log('DC updated: ' + dc);
}

// Affiche le statut
const acOk = ac !== null && typeof ac === 'number' && !isNaN(ac);
const dcOk = dc !== null && typeof dc === 'number' && !isNaN(dc);

node.status({
    fill: (acOk && dcOk) ? 'green' : 'yellow',
    shape: 'dot',
    text: 'AC:' + (acOk ? ac.toFixed(1) : '---') + ' | DC:' + (dcOk ? dc.toFixed(1) : '---')
});

// Si les deux sont valides, calcule
if (acOk && dcOk) {
    const sum = ac + dc;
    node.log('SUM: ' + ac + ' + ' + dc + ' = ' + sum);

    return {
        payload: sum,
        topic: 'PV/TotalPower',
        ac: ac,
        dc: dc,
        timestamp: new Date().toISOString()
    };
}

node.log('Waiting... AC:' + acOk + ' DC:' + dcOk);
return null;

var sumValue = msg.payload;
var timestamp = Date.now();

// Format InfluxDB Line Protocol pour VictoriaMetrics
// msg.payload DOIT contenir le line protocol (c'est le body envoye par http request)
var lineProtocol = 'total_solar_power{source="nodered",type="pv_total"} ' + sumValue + ' ' + timestamp;

// Sauvegarde les infos pour debug dans d'autres proprietes
msg.metricValue = sumValue;
msg.vmTimestamp = timestamp;
msg.acValue = msg.ac;
msg.dcValue = msg.dc;

// msg.payload = le body HTTP (le line protocol)
// msg.url = l'URL de destination
// msg.method = la methode HTTP
msg.payload = lineProtocol;
msg.url = 'http://192.168.1.141:8428/api/v1/import/prometheus';
msg.method = 'POST';

node.status({fill:"blue",shape:"dot",text:"Val: " + sumValue.toFixed(1) + "W"});

return msg;

var successCount = global.get('vm_solar_success') || 0;
successCount++;
global.set('vm_solar_success', successCount);

msg.payload = {
    status: "SUCCESS",
    statusCode: msg.statusCode,
    metricName: "total_solar_power",
    metricValue: msg.metricValue,
    acValue: msg.acValue,
    dcValue: msg.dcValue,
    timestamp: msg.vmTimestamp,
    totalSuccess: successCount,
    lineProtocolSent: msg.payload
};

node.status({fill:"green",shape:"dot",text:"OK #" + successCount});

return msg;

var errorCount = global.get('vm_solar_error') || 0;
errorCount++;
global.set('vm_solar_error', errorCount);

var errorDetails = {
    status: "ERROR",
    statusCode: msg.statusCode || "No Response",
    errorMessage: msg.payload || "Unknown error",
    metricName: "total_solar_power",
    metricValue: msg.metricValue,
    timestamp: msg.vmTimestamp,
    totalErrors: errorCount,
    url: 'http://192.168.1.141:8428/api/v1/import/prometheus'
};

if (msg.statusCode === 400) {
    errorDetails.errorType = "BAD REQUEST - Format de donnees invalide";
} else if (msg.statusCode === 404) {
    errorDetails.errorType = "NOT FOUND - Endpoint incorrect";
} else if (msg.statusCode === 500) {
    errorDetails.errorType = "SERVER ERROR - Probleme cote VictoriaMetrics";
} else if (!msg.statusCode) {
    errorDetails.errorType = "CONNECTION ERROR - Serveur injoignable";
} else {
    errorDetails.errorType = "UNKNOWN ERROR - Code: " + msg.statusCode;
}

msg.payload = errorDetails;

node.status({fill:"red",shape:"ring",text:"Erreur #" + errorCount});

return msg;

var successCount = global.get('vm_solar_success') || 0;
var errorCount = global.get('vm_solar_error') || 0;
var totalAttempts = successCount + errorCount;

msg.payload = {
    metricName: "total_solar_power",
    totalEnvoyes: totalAttempts,
    succes: successCount,
    erreurs: errorCount,
    tauxReussite: totalAttempts > 0 ? ((successCount / totalAttempts) * 100).toFixed(2) + '%' : 'N/A',
    derniereValeur: msg.metricValue || 'N/A',
    derniereSomme: msg.metricValue ? msg.metricValue.toFixed(2) + ' W' : 'N/A',
    dernierStatut: msg.payload.status || 'N/A'
};

return msg;

var query = 'count(total_solar_power)';

msg.url = 'http://192.168.1.141:8428/api/v1/query?query=' + encodeURIComponent(query);
msg.method = 'GET';

node.status({fill:"blue",shape:"dot",text:"Query..."});

return msg;

var response = msg.payload;
var result = {
    queryTime: new Date().toISOString(),
    metricName: "total_solar_power",
    rawResponse: response,
    status: response.status || "unknown"
};

if (response.status === "success" && response.data && response.data.result) {
    var results = response.data.result;

    if (results.length > 0) {
        var metricData = results[0];
        result.metricFound = true;
        result.totalDataPoints = metricData.value ? metricData.value[1] : "N/A";
        result.timestamp = metricData.value ? new Date(parseInt(metricData.value[0]) * 1000).toISOString() : "N/A";
        result.labels = metricData.metric || {};

        var sentCount = global.get('vm_solar_success') || 0;
        result.sentByNodeRED = sentCount;
        result.receivedByVM = parseInt(result.totalDataPoints) || 0;
        result.difference = sentCount - result.receivedByVM;
        result.syncStatus = result.difference === 0 ? "PARFAIT" : (result.difference > 0 ? "PERTES DETECTEES" : "VM A PLUS DE DONNEES");

        node.status({fill:"green",shape:"dot",text:"Data: " + result.totalDataPoints});
    } else {
        result.metricFound = false;
        result.message = "METRIC NON TROUVE - total_solar_power n'existe pas encore dans VictoriaMetrics";
        node.status({fill:"red",shape:"ring",text:"Non trouve"});
    }
} else {
    result.metricFound = false;
    result.error = response.error || "Reponse invalide";
    result.message = "ERREUR API: " + result.error;
    node.status({fill:"red",shape:"ring",text:"Erreur API"});
}

msg.payload = result;
return msg;

var result = msg.payload;

if (result.metricFound) {
    var syncInfo = {
        status: "SYNC_CHECK",
        metricName: "total_solar_power",
        sentByNodeRED: result.sentByNodeRED,
        storedInVM: result.receivedByVM,
        difference: result.difference,
        conclusion: result.syncStatus,
        recommendation: result.difference > 0 ? "Attendez quelques secondes et relancez la query (delai d'ingestion VM)" : "Tout est synchronise"
    };

    msg.payload = syncInfo;
    return msg;
}

return null;

var response = msg.payload;
var result = {
    totalMetrics: 0,
    solarMetrics: [],
    totalSolarPowerFound: false
};

if (response.status === "success" && response.data) {
    result.totalMetrics = response.data.length;

    response.data.forEach(function(metric) {
        if (metric.includes('solar') || metric.includes('pv') || metric.includes('power')) {
            result.solarMetrics.push(metric);
        }
        if (metric === 'total_solar_power') {
            result.totalSolarPowerFound = true;
        }
    });
}

result.message = result.totalSolarPowerFound ? 
    "total_solar_power TROUVE dans la liste des metrics!" : 
    "total_solar_power NON TROUVE dans la liste";

msg.payload = result;
return msg;

global.set('vm_solar_success', 0);
global.set('vm_solar_error', 0);

msg.payload = {
    status: "RESET",
    message: "Compteurs remis a zero",
    successCount: 0,
    errorCount: 0
};

node.status({fill:"grey",shape:"ring",text:"Reset"});

return msg;
